// Part: room: I-house upper east bedroom. Inner air x 32..33, y 8..11, z 10..15; door x31 z11 from the upper hall.
// Two white beds, foot z14 and head z15 against the back wall (facing south). A barrel dresser at the north end, a
// washstand (fence and top slab) with a standing lantern, and one hanging lantern over the lane. The lane x32 z11..13
// and the cells beside the beds stay clear from the door to both beds.
import { layers, bed } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const LEGEND = {
  B: "barrel",
  F: "spruce_fence",
  S: ["spruce_slab", { type: "top" }],
  L: ["lantern", { hanging: "false" }],
  H: ["lantern", { hanging: "true" }],
};

export function build(g) {
  // Focal piece: both beds, whole (bed() places foot and head with matching states).
  bed(g, [32, 8, 14], "south", "white");
  bed(g, [33, 8, 14], "south", "white");

  // Furniture as text, origin [32, 8, 10] (x32 z10 is the top-left interior cell); rows run along +x, then +z.
  // '.' and ' ' are left alone. Layer y8: barrel dresser at x32 z10, washstand legs at x33 z10.
  // Layer y9: washstand top slab. Layer y10: standing lantern on the top slab. Layer y11: hanging lantern at x32 z12.
  layers(g, [32, 8, 10], LEGEND, [
    ["BF", "..", "..", "..", "  ", "  "],
    [".S", "..", "..", "..", "  ", "  "],
    [".L", "..", "..", "..", "  ", "  "],
    ["..", "..", "H.", "..", "  ", "  "],
  ]);
}

